import java.util.*;

import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class Main {
    public static void main(String[] args) {
        JalankanTest.kelas(PesananTest.class);
    }
}

class PesananTest {
    Gudang gudang;
    Email email;
    Pesanan pesanan;

    @BeforeEach
    void siapkan() {
        gudang = mock(Gudang.class);
        email = mock(Email.class);
        pesanan = new Pesanan(gudang, email);
    }

    @Test
    void stokCukup() {
        when(gudang.stok("Kopi")).thenReturn(10);
        assertTrue(pesanan.pesan("Kopi", 3));
        verify(gudang).kurangi("Kopi", 3);
        verify(email).kirim("Pesanan Kopi x3 diterima");
    }

    @Test
    void stokKurang() {
        when(gudang.stok("Kopi")).thenReturn(2);
        assertFalse(pesanan.pesan("Kopi", 3));
        verify(gudang, never()).kurangi(anyString(), anyInt());
        verify(email).kirim("Maaf, stok Kopi tidak cukup");
    }
}

interface Gudang {
    int stok(String barang);

    void kurangi(String barang, int jumlah);
}

interface Email {
    void kirim(String pesan);
